const response = await fetch('https://formspring.io/api/v1/forms?per_page=10', {
  headers: {
    Authorization: `Bearer ${process.env.FORMSPRING_TOKEN}`,
    Accept: 'application/json',
  },
});

if (!response.ok) {
  throw new Error(`${response.status} ${await response.text()}`);
}

console.log(await response.json());

const response = await fetch('https://formspring.io/api/v1/forms', {
  method: 'POST',
  headers: {
    Authorization: `Bearer ${process.env.FORMSPRING_TOKEN}`,
    Accept: 'application/json',
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    name: 'Contact form',
    notification_emails: ['ops@example.com'],
  }),
});

console.log(await response.json());
